// Module-level memoized component — defined OUTSIDE RunDetail so React.memo
// is never bypassed by parent re-renders.  All props are primitives so shallow
// comparison is exact.  Changing project use (or any other RunDetail state)
// cannot cause this component to re-render or unmount Mapbox.
// Use-aware placeholder for the "Get specific — your concept" field
function conceptPlaceholder(projectType: string | null): string {
  const t = (projectType || '').toLowerCase();
  if (!t) return 'name your specific concept…';
  if (/coffee|cafe|café|bakery|boba|tea/.test(t)) return 'specialty coffee · boba · bakery café…';
  if (/restaurant|fast food|tavern|bar|cocktail|nightclub|cabaret|banquet|food/.test(t)) return 'Thai · Neapolitan pizza · taquería · steakhouse…';
  if (/day care|daycare|child|school/.test(t)) return 'bilingual · Montessori · infant/toddler…';
  if (/cannabis|dispensary/.test(t)) return 'recreational · medical…';
  if (/retail|store|shop|grocery|boutique|pharmacy/.test(t)) return 'boutique apparel · hardware · grocery…';
  return 'name your specific concept…';
}

// Use-specific license "verify" chip for the by-right verdict
function useLicenseChip(projectType: string | null): string | null {
  const t = (projectType || '').toLowerCase();
  if (/restaurant|fast food|bakery|coffee|cafe|café|food|grocery/.test(t)) return 'Retail food license · verify build-out';
  if (/tavern|bar|cocktail|nightclub|cabaret|liquor/.test(t)) return 'Liquor license · verify moratoriums';
  if (/day care|daycare|child/.test(t)) return 'DCFS license · verify facility standards';
  if (/cannabis|dispensary/.test(t)) return 'State cannabis license · verify buffers';
  if (/medical|dental|clinic|urgent care|pharmacy/.test(t)) return 'Professional/health licensing · verify';
  if (/salon|barber|spa|nail/.test(t)) return 'State cosmetology licensing · verify';
  if (/hotel|motel/.test(t)) return 'Hotel license · verify';
  return 'Verify use-specific licensing';
}

interface MapCardProps {
  lat: number; lon: number; zipCode: string; communityArea: string;
  ward: string | null; address: string; neighborhood?: string | null; tractGeoid?: string | null;
}
const MapCard = memo(function MapCard({ lat, lon, zipCode, communityArea, ward, address, neighborhood, tractGeoid }: MapCardProps) {
  return (
    <motion.div id="print-section-map" initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.12 }}>
      <Card className="border border-border">
        <CardHeader className="pb-2">
          <div className="flex items-center gap-3 flex-wrap">
            <CardTitle className="chead flex items-center gap-2">
              Location Map
            </CardTitle>
            <div className="lmap-views">
              <a
                href={`https://www.google.com/maps/@?api=1&map_action=pano&viewpoint=${lat},${lon}`}
                target="_blank" rel="noopener noreferrer"
                className="lmap-vbtn"
                data-testid="link-street-view"
              >
                <Eye /> Street View
              </a>
              <a
                href={`https://www.google.com/maps/@${lat},${lon},200m/data=!3m1!1e3`}
                target="_blank" rel="noopener noreferrer"
                className="lmap-vbtn"
                data-testid="link-google-earth"
              >
                <Globe /> Google Earth
              </a>
            </div>
          </div>
        </CardHeader>
        <CardContent>
          <div className="screen-only">
            <PropertyMap lat={lat} lon={lon} zipCode={zipCode} communityArea={communityArea} ward={ward} address={address} neighborhood={neighborhood} tractGeoid={tractGeoid} />
          </div>
          <div className="print-only hidden border border-border p-4 text-sm text-muted-foreground space-y-1">
            <p className="font-semibold text-foreground">Interactive map available in the live report</p>
            <p>{address}</p>
            <p>Coordinates: {lat.toFixed(6)}, {lon.toFixed(6)}</p>
            {zipCode && <p>ZIP: {zipCode} &nbsp;|&nbsp; Community Area: {communityArea} &nbsp;|&nbsp; Ward {ward}</p>}
          </div>
        </CardContent>
      </Card>
    </motion.div>
  );
});

const DEMOGRAPHIC_FAVORABILITY: Record<string, 'up' | 'down'> = {
  'median household income': 'up', 'per capita income': 'up', 'median home value': 'up',
  '% below poverty': 'down', '% unemployed': 'down', '% without hs diploma': 'down', '% housing vacancy': 'down',
};
const demographicChangeClass = (label: string, up: boolean | null) => {
  if (up === null) return 'demo-neutral';
  const key = label.toLowerCase();
  const direction = Object.entries(DEMOGRAPHIC_FAVORABILITY).find(([name]) => key.includes(name))?.[1];
  return direction ? (up === (direction === 'up') ? 'demo-good' : 'demo-bad') : 'demo-neutral';
};

