  const { data: regularRun, isLoading: isRegularRunLoading } = useRun(isStandaloneReport ? null : id);
  const { data: publicRun, isLoading: isPublicRunLoading } = usePublicRun(isStandaloneReport ? id : null);
  const run = isStandaloneReport ? publicRun : regularRun;
  const isRunLoading = isStandaloneReport ? isPublicRunLoading : isRegularRunLoading;
  const { data: listingData } = useListingData(run?.id);
  const { data: listingSnapshot, isFetched: listingSnapshotFetched, isError: isListingSnapshotError, error: listingSnapshotError } = useListingSnapshot(run?.id);
  const generateListingSnapshot = useGenerateListingSnapshot(run?.id);
  const updateRunLabel = useUpdateRunLabel();
  const [isEditingLabel, setIsEditingLabel] = useState(false);
  const [labelDraft, setLabelDraft] = useState('');
  // Auto-check the live listing once per run when no snapshot exists yet (owner views only).
  const listingAutoCheckedRef = useRef<number | null>(null);
  useEffect(() => {
    if (isStandaloneReport) return; // public/report views can't trigger the paid lookup
    if (!run?.id || !listingSnapshotFetched) return;
    if (listingSnapshot) return; // already have a saved snapshot
    if (generateListingSnapshot.isPending || generateListingSnapshot.isError) return;
    if (listingAutoCheckedRef.current === run.id) return;
    listingAutoCheckedRef.current = run.id;
    generateListingSnapshot.mutate({});
  }, [isStandaloneReport, run?.id, listingSnapshotFetched, listingSnapshot, generateListingSnapshot]);
  // Declare early so the geocode useEffect below can reference it
  const { isSubscriber, user: authUser } = useAuth();
  // Report is unlocked if user is a subscriber or the run has been purchased
  const isReportUnlocked = isSubscriber || !!run?.purchasedAt;
  // Project use locks after 90 days — subscribers are never locked
  const isProjectTypeLocked = !isSubscriber && !!run && (() => {
    const startDate = run.createdAt || run.purchasedAt;
    if (!startDate) return false;
    const ms = Date.now() - new Date(startDate).getTime();
    return ms > 90 * 24 * 60 * 60 * 1000;
  })();
  const geocode = useGeocodeLookup();
  const { data: businessUsesData } = useBusinessUses();
  const updateProjectType = useUpdateProjectType();
  const updateFunnelAnswers = useUpdateFunnelAnswers();
  const updateManualProperty = useUpdateManualProperty();
  const [isSubmittingReport, setIsSubmittingReport] = useState(false);
  const [showFunnelEdit, setShowFunnelEdit] = useState(false);
  const toggleFavorite = useToggleFavorite();

  // Manual property entry state
  const [manualBuildingSqFt, setManualBuildingSqFt] = useState<string>("");
  const [manualLandSqFt, setManualLandSqFt] = useState<string>("");
  const [manualStories, setManualStories] = useState<string>("");
  const [showManualEntryForm, setShowManualEntryForm] = useState(false);
